    public PurchaseOrder testCreate() throws Throwable {
    PurchaseOrder entity = null;

    LOGGER.info( "PurchaseOrderTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a PurchaseOrder");

    StringBuilder msg = new StringBuilder( "-- Failed to create a PurchaseOrder" );

    try {
        entity = service.createPurchaseOrder( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getPurchaseOrderId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a PurchaseOrder with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

