    /**
     * Tests getting all PurchaseOrders.
     *
     * @return    Collection
     */
    public List<PurchaseOrder> testGetAll() throws Throwable {
    LOGGER.info( "PurchaseOrderTest:testGetAll() - Retrieving Collection of PurchaseOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PurchaseOrder : " );
    List<PurchaseOrder> collection  = null;

    try {
        // call the static get method on the PurchaseOrderService
        collection = service.getAllPurchaseOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PurchaseOrder currEntity  = null;
            Iterator<PurchaseOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPurchaseOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

